BEGIN;
SELECT set_config('test.usuario',(SELECT u.id_usuario::text FROM public.usuarios u JOIN public.roles r ON r.id_rol=u.rol_id WHERE u.activo AND r.nombre='ADMINISTRADOR' LIMIT 1),true);
SELECT set_config('request.jwt.claims',json_build_object('sub',current_setting('test.usuario'),'role','authenticated')::text,true);
DO $fixtures$
DECLARE cat integer;prov integer;a integer;b integer;c integer;d integer;
BEGIN
  INSERT INTO public.categorias(nombre) VALUES('__TEST_INICIAL_CAT__') RETURNING id_categoria INTO cat;
  INSERT INTO public.proveedores(nombre) VALUES('__TEST_INICIAL_PROV__') RETURNING id_proveedor INTO prov;
  PERFORM set_config('test.prov',prov::text,true);
  INSERT INTO public.productos(categoria_id,nombre,precio_venta,controla_lotes) VALUES(cat,'__TEST_INICIAL_LOTES__',5,true) RETURNING id_producto INTO a;
  INSERT INTO public.productos(categoria_id,nombre,precio_venta) VALUES(cat,'__TEST_INICIAL_SIMPLE__',5) RETURNING id_producto INTO b;
  INSERT INTO public.productos(categoria_id,nombre,precio_venta,controla_lotes) VALUES(cat,'__TEST_INICIAL_INVALIDO__',5,true) RETURNING id_producto INTO c;
  INSERT INTO public.productos(categoria_id,nombre,precio_venta,existencia) VALUES(cat,'__TEST_INICIAL_EXISTENTE__',5,1) RETURNING id_producto INTO d;
  PERFORM set_config('test.a',a::text,true);PERFORM set_config('test.b',b::text,true);PERFORM set_config('test.c',c::text,true);PERFORM set_config('test.d',d::text,true);
END;
$fixtures$;
SET LOCAL ROLE authenticated;
DO $test$
DECLARE a integer:=current_setting('test.a')::integer;b integer:=current_setting('test.b')::integer;c integer:=current_setting('test.c')::integer;d integer:=current_setting('test.d')::integer;
  uuid uuid:=gen_random_uuid();r jsonb;partidas jsonb;lot_a integer;lot_b integer;venta integer;tr integer;
  v_compras bigint;v_deudas bigint;v_caja bigint;antes_costos numeric;hoy date:=(CURRENT_TIMESTAMP AT TIME ZONE 'America/Guatemala')::date;
BEGIN
  SELECT count(*) INTO v_compras FROM public.compras;SELECT count(*) INTO v_deudas FROM public.cuentas_por_pagar;SELECT count(*) INTO v_caja FROM public.caja_eventos;
  partidas:=jsonb_build_array(jsonb_build_object('numero_lote','A','fecha_vencimiento',hoy+1,'cantidad',5,'costo_unitario','2.00'),jsonb_build_object('numero_lote','B','fecha_vencimiento',hoy+20,'cantidad',7,'costo_unitario','3.00'));
  r:=public.registrar_inventario_inicial(uuid,a,partidas,'Conteo inicial real');
  ASSERT (r->>'cantidad')::integer=12 AND (r->>'valor_inicial')::numeric=31,'Cantidad o valor inicial incorrecto';
  lot_a:=(r->'partidas'->0->>'lote_id')::integer;lot_b:=(r->'partidas'->1->>'lote_id')::integer;
  ASSERT public.fn_stock_lote(lot_a)=5 AND public.fn_stock_lote(lot_b)=7,'No creó existencias por lote';
  ASSERT (SELECT existencia=12 AND ultimo_costo=2.58 FROM public.productos WHERE id_producto=a),'Costo de referencia o existencia incorrectos';
  r:=public.registrar_inventario_inicial(uuid,a,partidas,'Conteo inicial real');
  ASSERT (r->>'repetida')::boolean AND (SELECT count(*)=2 FROM public.lotes WHERE entrada_inicial_id=(r->>'id_inicial')::bigint),'Duplicó lotes al reintentar';
  BEGIN PERFORM public.registrar_inventario_inicial(uuid,a,partidas,'Otro motivo');RAISE EXCEPTION 'Aceptó UUID con datos distintos';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
  BEGIN PERFORM public.registrar_inventario_inicial(gen_random_uuid(),a,partidas,'Otra carga');RAISE EXCEPTION 'Aceptó segunda carga inicial';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
  ASSERT (SELECT count(*)=v_compras FROM public.compras) AND (SELECT count(*)=v_deudas FROM public.cuentas_por_pagar) AND (SELECT count(*)=v_caja FROM public.caja_eventos),'La carga creó compra, deuda o caja';
  r:=public.obtener_inventario_producto(a,0);
  ASSERT (r->>'total_lotes')::integer=2 AND (r->>'suma_lotes')::integer=12 AND r->'lotes'->0->>'origen'='LOTE_INICIAL','Inventario no reconoce lotes iniciales';
  r:=public.obtener_dashboard();ASSERT EXISTS(SELECT 1 FROM jsonb_array_elements(r->'vencimientos')x WHERE (x->>'id_lote')::integer=lot_a),'Dashboard omitió vencimientos iniciales';
  r:=public.obtener_lista_compras('__TEST_INICIAL_LOTES__','nombre',false,0);
  ASSERT (r->'candidatos'->0->>'disponible')::integer=12 AND NOT (r->'candidatos'->0->>'inconsistente')::boolean,'Lista de compras no incluye iniciales';
  r:=public.obtener_rotacion_productos(hoy,hoy,7,'__TEST_INICIAL_LOTES__');
  ASSERT (r->'productos'->0->>'disponible')::integer=12 AND NOT (r->'productos'->0->>'inconsistente')::boolean,'Rotación no incluye iniciales';
  SELECT id_forma_pago INTO tr FROM public.formas_pago WHERE nombre='TRANSFERENCIA';
  r:=public.registrar_venta_segura(gen_random_uuid(),null,tr,jsonb_build_array(jsonb_build_object('producto_id',a,'cantidad',6)),null);venta:=(r->>'id_venta')::integer;
  ASSERT public.fn_stock_lote(lot_a)=0 AND public.fn_stock_lote(lot_b)=6,'Venta no aplicó FEFO a iniciales';
  ASSERT (SELECT sum(costo_total_venta)=13 AND bool_and(origen_costo_venta='LOTE_INICIAL') FROM public.movimientos_inventario WHERE detalle_venta_id IN(SELECT id_detalle_venta FROM public.detalle_ventas WHERE venta_id=venta)),'No conservó costo inicial por lote';
  r:=public.obtener_reporte_costos(hoy,hoy);
  ASSERT EXISTS(SELECT 1 FROM jsonb_array_elements(r->'mayores')x WHERE (x->>'id_producto')::integer=a),'Reporte de utilidad omitió venta inicial';
  PERFORM public.registrar_ajuste_inventario(gen_random_uuid(),a,lot_b,'CONTEO',5,6,'Corrección de conteo');
  ASSERT public.fn_stock_lote(lot_b)=5 AND (SELECT existencia=5 FROM public.productos WHERE id_producto=a),'No ajustó lote inicial';
  PERFORM public.registrar_compra(current_setting('test.prov')::integer,tr,'TEST-INICIAL-COMPRA',jsonb_build_array(jsonb_build_object('producto_id',a,'cantidad',2,'costo_unitario',9,'lotes',jsonb_build_array(jsonb_build_object('numero_lote','COMPRA-NUEVA','cantidad',2,'fecha_vencimiento',hoy+10)))),null);
  ASSERT (SELECT sum(costo_total_venta)=13 FROM public.movimientos_inventario WHERE detalle_venta_id IN(SELECT id_detalle_venta FROM public.detalle_ventas WHERE venta_id=venta)),'Una compra posterior cambió el costo de la venta inicial';
  r:=public.registrar_venta(null,tr,jsonb_build_array(jsonb_build_object('producto_id',a,'cantidad',6)),null);
  ASSERT (SELECT sum(costo_total_venta)=30 AND count(DISTINCT origen_costo_venta)=2 FROM public.movimientos_inventario WHERE detalle_venta_id IN(SELECT id_detalle_venta FROM public.detalle_ventas WHERE venta_id=(r->>'id_venta')::integer)),'No mezcló lotes iniciales y compras con sus costos propios';
  PERFORM public.registrar_inventario_inicial(gen_random_uuid(),b,jsonb_build_array(jsonb_build_object('cantidad',4,'costo_unitario','1.25')),'Inicial sin lotes');
  r:=public.registrar_venta(null,tr,jsonb_build_array(jsonb_build_object('producto_id',b,'cantidad',1)),null);
  ASSERT (SELECT costo_unitario_venta=1.25 AND origen_costo_venta='ULTIMO_COSTO' FROM public.movimientos_inventario WHERE detalle_venta_id IN(SELECT id_detalle_venta FROM public.detalle_ventas WHERE venta_id=(r->>'id_venta')::integer)),'No guardó costo inicial sin lotes';
  BEGIN PERFORM public.registrar_inventario_inicial(gen_random_uuid(),d,jsonb_build_array(jsonb_build_object('cantidad',1,'costo_unitario','1')),'Existente');RAISE EXCEPTION 'Aceptó producto con stock previo';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
  BEGIN PERFORM public.registrar_inventario_inicial(gen_random_uuid(),c,jsonb_build_array(jsonb_build_object('numero_lote','X','cantidad',1,'costo_unitario','1','fecha_vencimiento',hoy-1)),'Vencido');RAISE EXCEPTION 'Aceptó lote vencido';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
  BEGIN PERFORM public.registrar_inventario_inicial(gen_random_uuid(),c,jsonb_build_array(jsonb_build_object('numero_lote','X','cantidad',0,'costo_unitario','1')),'Cero');RAISE EXCEPTION 'Aceptó cantidad cero';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
  BEGIN PERFORM public.registrar_inventario_inicial(gen_random_uuid(),c,jsonb_build_array(jsonb_build_object('numero_lote','X','cantidad',1,'costo_unitario','1.001')),'Costo');RAISE EXCEPTION 'Aceptó costo con tres decimales';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
  BEGIN PERFORM public.registrar_inventario_inicial(gen_random_uuid(),c,jsonb_build_array(jsonb_build_object('numero_lote','X','cantidad',1,'costo_unitario','1'),jsonb_build_object('numero_lote','X','cantidad',2,'costo_unitario','1')),'Duplicado');RAISE EXCEPTION 'Aceptó lote repetido';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
  ASSERT NOT EXISTS(SELECT 1 FROM public.inventarios_iniciales WHERE producto_id=c),'Una validación fallida dejó carga parcial';
  BEGIN UPDATE public.inventarios_iniciales SET resultado='{}' WHERE producto_id=a;RAISE EXCEPTION 'Permitió escritura directa';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
  ASSERT NOT has_function_privilege('anon','public.registrar_inventario_inicial(uuid,integer,jsonb,text)','EXECUTE'),'Permitió acceso anon';
  PERFORM set_config('request.jwt.claims','{"role":"authenticated"}',true);
  BEGIN PERFORM public.registrar_inventario_inicial(gen_random_uuid(),c,partidas,'Sin sesión');RAISE EXCEPTION 'Aceptó sin sesión';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
END;
$test$;
ROLLBACK;
SELECT 'OK: carga por lotes/sin lotes, costos, FEFO, ajustes, alertas, reportes, reintentos, historial y sin compras/deudas/caja. Datos revertidos.' AS resultado;
